INSERT OR REPLACE INTO observations (id,dataset_id,label,year,place,toll,cause,confidence,tier,tier_basis,source_id) VALUES ('wisqars-1-4-2024','lsl-water-deaths-ledger','U.S. drowning, ages 1 to 4, a later year','2024','United States','492','drowning','counted','T1','tiers-v2','cdc-wisqars-10-leading-causes-of-injury-deaths-2024');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('ilo-fishing','fish-safety','Same occupation. Two estimates. A quarter century apart. Averaging them invents a third number nobody counted.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('ilo-2024','ilo-fishing','449 is a filed merchant-fleet register. 24,000 is an old global fishing estimate. They are not the same people and they are not a sum.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('us-rec-2024','us-fishing','556 is one year of U.S. recreational boating. 1,055 is nineteen years of U.S. commercial fishing. A harbor that mixes them will brief the wrong boat.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('mediterranean','iom-all','The Mediterranean figure is already inside the global migration figure. Adding them counts the same dead twice.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('cdc-drown-2018','cdc-drown-2020','4,345 a year is the 2018–2021 average. Over 4,500 a year is 2020–2022. The windows overlap. Averaging them invents a third United States.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('cdc-drown-2018','cpsc-pool-2026','4,345 is every setting and every age. 376 is pool and spa deaths of children under 15, reported to a different agency. Subtracting one from the other pretends they were counted the same way.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('cdc-child-2022','wisqars-1-4-2024','461 and 492 are both ages 1–4, and they are different years. They are not a trend you can draw from two dots, and neither one is a pool count.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('cpsc-pool-2026','cpsc-home','Nearly 90 children a year inside the home, mostly the bath, is not the pool file. Adding them builds a child-drowning total the reports refused to publish as one number.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('cdc-drown-2018','us-rec-2024','556 is pleasure boats. 4,345 is every unintentional drowning. The boats are inside the larger count only in the loose sense that some of the dead were boating. The years do not match. Do not subtract.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('cdc-drown-2018','who-drowning','One country, counted. The world, estimated. A lab that divides 4,345 by 236,000 and calls it the American share has invented a percentage.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('who-drowning','who-2021','236,000 is still printed on WHO’s health-topics page. The 2021 status report says 300,000, and the fact sheet of 1 May 2026 says around 300,000 a year. Same agency, two estimates. Do not average them, and do not add either to a fishing total.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('peterson-2022','cdc-drown-2020','4,509 is the count for 2022 in one paper. Over 4,500 a year is the 2020–2022 window. The year sits inside the window. Do not average them.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('peterson-pool','cpsc-pool-2026','840 is all ages, death certificates, swimming pools, 2022. 376 a year is children under 15, pool or spa, reported to CPSC for 2021–2023. The 2022 CPSC count is 359, not 840. Do not average them.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('peterson-craft','us-rec-2024','341 is watercraft drownings on 2022 death certificates. 556 is the Coast Guard’s recreational boating census for 2024, and not all of those deaths were drownings. Different years, different systems.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('usla-rescues','usla-guarded','A rescue is not a death. 85,258 and 32 are two columns of one report from the agencies that filed. Do not subtract them and call the difference lives saved.');
INSERT OR REPLACE INTO non_additive_pairs VALUES ('usla-guarded','usla-unguarded','32 and 118 are the guarded and unguarded columns. The association did not publish 150. Beaches that did not report are in neither column.');
